import{bV as a,aL as t,u as r,G as i}from"./chunks/framework.C8THFwVE.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"郜健宇的个人博客","text":"","tagline":"想要就争取，不行就努力","actions":[{"theme":"brand","text":"个人介绍","link":"/markdown-examples"},{"theme":"alt","text":"API Examples","link":"/api-examples"}]},"features":[{"title":"Feature A","details":"Lorem ipsum dolor sit amet, consectetur adipiscing elit"},{"title":"Feature B","details":"Lorem ipsum dolor sit amet, consectetur adipiscing elit"},{"title":"Feature C","details":"Lorem ipsum dolor sit amet, consectetur adipiscing elit"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function l(n,e,p,h,s,d){return t(),r("div",null,[...e[0]||(e[0]=[i('<h2 id="inner-peace" tabindex="-1">Inner Peace <a class="header-anchor" href="#inner-peace" aria-label="Permalink to &quot;Inner Peace&quot;">​</a></h2><p>咕咕嘎嘎！！！</p><p>我嘞个飞天大脚！！！</p><p><a href="https://www.bilibili.com/video/BV1vm7A6UERh" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1vm7A6UERh</a></p><hr><h2 id="《个人使命宣言》" tabindex="-1">《个人使命宣言》 <a class="header-anchor" href="#《个人使命宣言》" aria-label="Permalink to &quot;《个人使命宣言》&quot;">​</a></h2><h3 id="一、核心总纲领" tabindex="-1">一、核心总纲领 <a class="header-anchor" href="#一、核心总纲领" aria-label="Permalink to &quot;一、核心总纲领&quot;">​</a></h3><p>我以品德为根基，以能量为驱动。<br> 正直，是我与世界互信的货币；积极主动，是我对自己负责的态度。<br> 向内，我直面自己的缺点；向外，我支持他人的可能 —— 做一个对自己诚实、让世界信赖的人。</p><h3 id="二、价值原则" tabindex="-1">二、价值原则 <a class="header-anchor" href="#二、价值原则" aria-label="Permalink to &quot;二、价值原则&quot;">​</a></h3><h4 id="_1-我选择用品德-赢得我的人生" tabindex="-1">1 我选择用品德，赢得我的人生 <a class="header-anchor" href="#_1-我选择用品德-赢得我的人生" aria-label="Permalink to &quot;1 我选择用品德，赢得我的人生&quot;">​</a></h4><p>对外，当旁人用讨好、夸大或捷径谋取利益时，我只凭真实的能力和价值去争取机会。我追求的不是对抗式的清高，而是有韧性的真实：我会坚持真诚，也接受现实复杂，包括真实可能被误读；如果因此失去什么，那只说明那个机会与我的方式不适配，而不说明我要变成另一个人。</p><p>对内，这份坚定同样适用于我与自己的关系：当我想逃避、拖延或自我欺骗时，我拒绝做自己的逃兵。我会为自己制定冷静、具体、可执行的方案，对自己负责。</p><p>我的目标，不是成为人人喜欢的人，而是成为一个值得自己信赖、也值得他人信赖的人。</p><h4 id="_2-我选择以良善和尊重-去接住那些比我稚嫩或身处低谷的人" tabindex="-1">2 我选择以良善和尊重，去接住那些比我稚嫩或身处低谷的人 <a class="header-anchor" href="#_2-我选择以良善和尊重-去接住那些比我稚嫩或身处低谷的人" aria-label="Permalink to &quot;2  我选择以良善和尊重，去接住那些比我稚嫩或身处低谷的人&quot;">​</a></h4><p>我曾被人真诚地接住过，那种被关注、被在意的体验，是我愿意传递下去的火种。</p><p>当面对比我资历浅、力量弱的人，我会回想自己当初最需要的是什么 —— 不是立刻被评判和指导，而是先被理解，再被支持。那位前辈没有急着给建议，而是先问：“你现在状态怎么样？”然后问：“需要点什么帮助嘛？”。</p><p>如今轮到我，我也先给予接纳，再给予方法。这不是居高临下的帮助，而是设身处地的懂得：一个人先被接住，才有力气往上走。</p><h4 id="_3-我选择用积极的能量-去解读现实、回应挑战" tabindex="-1">3 我选择用积极的能量，去解读现实、回应挑战 <a class="header-anchor" href="#_3-我选择用积极的能量-去解读现实、回应挑战" aria-label="Permalink to &quot;3 我选择用积极的能量，去解读现实、回应挑战&quot;">​</a></h4><p>这不是相信『明天会更好』的童话，而是牢牢握住『我能影响事态』的主动权。</p><p>我的高能量状态，来自一个清晰的分界：把力气花在我能推动的事情上，把平静留给那些不由我决定的部分。当焦虑、浮躁或无力感袭来，这个念头就是切断内耗的开关 —— 它会立刻把我的精力，导向下一个最小的、我能控制的积极行动。</p><p>我不是环境的被动反应者，而是自己能量的主动创造者。</p><h4 id="_4-我选择把心中的重视-翻译成对方能感受到的关心。" tabindex="-1">4 我选择把心中的重视，翻译成对方能感受到的关心。 <a class="header-anchor" href="#_4-我选择把心中的重视-翻译成对方能感受到的关心。" aria-label="Permalink to &quot;4 我选择把心中的重视，翻译成对方能感受到的关心。&quot;">​</a></h4><p>若我表达重视的方式，对方理解不到，那这份在意便很难真正抵达对方心里。</p><p>所以，当重要的人向我表露困难或消极时，我会先按下解决问题的本能，先说一句“我看到你很不容易”。在给出任何道理之前，我会停下来问自己：如果此刻我没能让她感受到我的在乎，那么接下来的每一句话，都可能成为我们之间的一道墙。</p><p>真正的在乎，不是先急着替她解决一切，而是先让她知道：我会在你身边，你不需要独自面对；然后，再一起去解决该解决的事。</p><h3 id="三、边界守护誓言" tabindex="-1">三、边界守护誓言 <a class="header-anchor" href="#三、边界守护誓言" aria-label="Permalink to &quot;三、边界守护誓言&quot;">​</a></h3><p>当世界用焦虑与诱惑向我猛攻，试图让我放弃原则或变得冷漠，我会挺直脊背，用我信的方式去赢，用我懂的方式去爱。</p><p>当内心的旧声音再次响起，把我拉回“明明知道该做，却仍在拖延、逃避或停在原地”的状态，我会对自己说：不必用大道理审判自己，只需问“此刻最小的行动是什么”，然后去做。此刻，我选择做自己的贵人，而不是自己人生的路人</p><p>向外，我守原则；向内，我守行动。原则让我选择做正确的事，行动让我不再停在原地。它们不是口号，而是我每天具体的选择。</p><hr>',30)])])}const u=a(o,[["render",l]]);export{m as __pageData,u as default};
